                      <span style={{ color: C.muted, fontWeight: 400, fontSize: "9px" }}>فرۆشرا</span>
                    </span>
                  </div>
                  <div className="w-full rounded-full overflow-hidden" style={{ height: "3px", background: "rgba(255,255,255,0.06)" }}>
                    <div className="h-full rounded-full transition-all duration-700"
                      style={{ width: `${item.pct}%`, background: `linear-gradient(90deg,${VIOLET},${C.cyan})` }} />
                  </div>
                </div>
              ))}
            </div>

            {/* Low Stock Alerts */}
            <div className="flex items-center gap-2 mb-3">
              <Bell className="w-3.5 h-3.5" style={{ color: C.orange }} />
              <h3 className="text-[11px] font-extrabold" style={{ color: C.orange }}>ئاگادارکردنەوەی کاڵای کەم</h3>
            </div>
            <div className="space-y-1.5">
              {LOW_STOCK.map(item => (
                <div key={item.name} className="flex items-center justify-between rounded-lg px-3 py-2"
                  style={{ background: item.urgent ? "rgba(239,68,68,0.06)" : "rgba(255,255,255,0.022)", border: `1px solid ${item.urgent ? "rgba(239,68,68,0.18)" : "rgba(255,255,255,0.05)"}` }}>
                  <div className="flex items-center gap-2">
                    {item.urgent && <AlertTriangle className="w-3 h-3 shrink-0" style={{ color: "#f87171" }} />}
                    <span className="text-[10px] font-semibold" style={{ color: item.urgent ? "#f87171" : C.sub }}>{item.name}</span>
                  </div>
                  <span className="text-[10px] font-extrabold" style={{ color: item.urgent ? "#f87171" : C.muted }}>
                    {item.qty}&nbsp;<span style={{ fontWeight: 400, fontSize: "9px" }}>{item.unit}</span>
                  </span>
                </div>
              ))}
            </div>
          </motion.div>

          {/* Recent Purchases Table */}
          <motion.div
            initial={{ opacity: 0, y: 18 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.53, duration: 0.38 }}
            className="xl:col-span-2"
            style={{ ...glassCard(), padding: "20px" }}
          >
            <div className="flex items-center gap-2 mb-5">
              <div className="w-8 h-8 rounded-lg flex items-center justify-center"
                style={{ background: `${C.cyan}1a`, border: `1px solid ${C.cyan}40` }}>
                <PackageCheck className="w-4 h-4" style={{ color: C.cyan }} />
              </div>
              <div>
                <h2 className="text-[13px] font-extrabold leading-none" style={{ color: C.text }}>دوایین کڕینەکان</h2>
                <p className="text-[10px] mt-0.5" style={{ color: C.muted }}>نوێترین مامەڵەکانی فرۆشگا</p>
              </div>
            </div>
            <div className="overflow-hidden rounded-xl" style={{ border: "1px solid rgba(255,255,255,0.05)" }}>
              <table className="w-full">
                <thead>
                  <tr style={{ background: "rgba(255,255,255,0.03)", borderBottom: "1px solid rgba(255,255,255,0.05)" }}>
                    {["#", "کڕیار", "دانە", "جۆری پارەدان", "کۆی گشتی", "کات"].map(h => (
                      <th key={h} className="px-3 py-3 text-start font-bold uppercase tracking-wide"
                        style={{ color: C.muted, fontSize: "9px" }}>{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {RECENT_PURCHASES.map((p, idx) => (
                    <tr key={p.id}
                      style={{ borderBottom: idx < RECENT_PURCHASES.length - 1 ? "1px solid rgba(255,255,255,0.04)" : "none" }}
                      onMouseEnter={e => { (e.currentTarget as HTMLElement).style.background = "rgba(255,255,255,0.025)"; }}
                      onMouseLeave={e => { (e.currentTarget as HTMLElement).style.background = "transparent"; }}
                    >
                      <td className="px-3 py-3">
                        <div className="flex items-center gap-1.5">
                          <PulseDot color={C.green} size="h-1.5 w-1.5" />
                          <span className="font-mono font-bold" style={{ color: C.muted, fontSize: "10px" }}>#{p.id}</span>
                        </div>
                      </td>
                      <td className="px-3 py-3 font-bold" style={{ color: C.text, fontSize: "11px" }}>{p.customer}</td>
                      <td className="px-3 py-3" style={{ color: C.sub, fontSize: "10px" }}>{p.items} دانە</td>
                      <td className="px-3 py-3">
                        <span className="inline-flex items-center px-2 py-0.5 rounded-md font-bold"
                          style={{ fontSize: "9px", background: p.method === "نەقد" ? "rgba(16,185,129,0.10)" : p.method === "قەرز" ? "rgba(239,68,68,0.10)" : "rgba(59,130,246,0.10)", color: p.method === "نەقد" ? "#34d399" : p.method === "قەرز" ? "#f87171" : "#60a5fa", border: p.method === "نەقد" ? "1px solid rgba(16,185,129,0.20)" : p.method === "قەرز" ? "1px solid rgba(239,68,68,0.20)" : "1px solid rgba(59,130,246,0.20)" }}>
                          {p.method}
                        </span>
                      </td>
                      <td className="px-3 py-3">
                        <span className="font-extrabold tabular-nums" style={{ color: VIOLET, fontSize: "11px" }}>
                          {new Intl.NumberFormat("ku-IQ").format(p.total)}
                        </span>
                        <span style={{ color: C.muted, fontSize: "9px", marginInlineStart: "3px" }}>د.ع</span>
                      </td>
                      <td className="px-3 py-3" style={{ color: C.muted, fontSize: "10px" }}>{p.time}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </motion.div>

        </div>
      </div>
    </div>
  );
}

import { useAuth } from "@/contexts/AuthContext";
import DistributorDashboard from "./dashboard-distributor";
import FactoryDashboard     from "./dashboard-factory";
import MarketDashboard      from "./dashboard-market";

/* ─────────────────────────────────────────────────────────────────────
   SECTOR → DASHBOARD ROUTER
   Priority:
   1. user.sectorKey  (set during registration, persisted on AuthUser)
   2. localStorage.getItem('linqi_sector')  (fallback for offline/cached)
   3. 'other'  → defaults to MarketDashboard
────────────────────────────────────────────────────────────────────── */
export default function Dashboard() {
  const { user } = useAuth();

  const sector: string =
    (user as any)?.sectorKey ??
    localStorage.getItem("linqi_sector") ??
    "other";

  switch (sector) {
    case "distributor":
      return <DistributorDashboard />;

    case "manufacturer":
      return <FactoryDashboard />;

    case "supermarket":
    case "retail_shop":
    case "restaurant":
    case "hotel":
    case "pharmacy":
    case "hospital":
    case "office":
    case "delivery":
    case "other":
    default:
      return <MarketDashboard />;
  }
}

